// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SafetyAssertion) predicate.SafetyAssertion {
	return predicate.SafetyAssertion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SafetyAssertion) predicate.SafetyAssertion {
	return predicate.SafetyAssertion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SafetyAssertion) predicate.SafetyAssertion {
	return predicate.SafetyAssertion(sql.NotPredicates(p))
}
